export function operation(name){
  let spec = operations[name];
  if(!spec){
    throw new Error("Unknown substrate operation: " + name);
  }
  return spec;
}

export function restOperation(path,method){
  method = (method || "GET");
  let pathname = new URL(path,"https://local.invalid")["pathname"];
  for(let spec of Object.values(operations)){
    if((spec["transport"] == "rest") && (spec["method"] == method) && new RegExp(
      "^" + spec["path"].replace(new RegExp(":[a-z]+","g"),"[^/]+") + "$"
    ).test(pathname)){
      return spec;
    }
  };
  throw new Error("Unknown substrate endpoint: " + method + " " + pathname);
}

export var RELATED = {
  "siteAdmin":["sites","siteSubmissions"],
  "member":["community","logbook","posts","trips"],
  "admin":["instagram","posts","member"],
  "eventsMember":["eventsPublic","directoryPublic"],
  "directoryOwner":["directoryPublic","directoryAdmin"],
  "directoryAdmin":["directoryPublic","directoryOwner"],
  "logbook":["community","trips","member","instagram"],
  "instagram":["posts","member","admin","logbook"],
  "posts":["member"],
  "invitations":["member"],
  "community":["member","logbook","posts","trips"],
  "siteSubmissions":["siteAdmin"]
};

export function affectedDomains(spec){
  return Array.from(
    new Set([spec["domain"]].concat(RELATED[spec["domain"]] || []))
  );
}